import { describe, expect, it } from "vitest";
import { readFileSync } from "node:fs";
import { KEPT_HEIGHT, LeanSphincsKey, PK_LENGTH, SIG_LENGTH, verify } from "../src/index.js";

// Generated by scripts/gen-vectors.mjs with the NATIVE @kevaundray/lean-pq 0.7.0, the LeanPool node's signer.
const vectors = JSON.parse(readFileSync(new URL("../vectors/lean-pq-0.7.0.json", import.meta.url), "utf8")) as {
  cases: { seed: string; keptHeight: number; publicKey: string; message: string; signature: string }[];
};
const b = (h: string) => Uint8Array.from(Buffer.from(h.slice(2), "hex"));
const h = (u: Uint8Array) => `0x${Buffer.from(u).toString("hex")}`;

describe("leanSPHINCS WASM vs native lean-pq 0.7.0", () => {
  it("has the vectors' sizes", () => {
    expect(vectors.cases.length).toBeGreaterThan(0);
    for (const c of vectors.cases) {
      expect(b(c.publicKey).length).toBe(PK_LENGTH);
      expect(b(c.signature).length).toBe(SIG_LENGTH);
      expect(c.keptHeight).toBe(KEPT_HEIGHT);
    }
  });

  it("derives the same public key and the same (deterministic) signature from the same seed", () => {
    for (const c of vectors.cases) {
      const key = LeanSphincsKey.fromSeed(b(c.seed));
      expect(h(key.publicKey)).toBe(c.publicKey);
      const sig = key.sign(b(c.message));
      expect(h(sig)).toBe(c.signature);
      key.dispose();
    }
  });

  it("accepts the native signatures and refuses tampering", () => {
    for (const c of vectors.cases) {
      expect(verify(b(c.publicKey), b(c.message), b(c.signature))).toBe(true);
      const bad = b(c.signature);
      bad[200] = bad[200]! ^ 1;
      expect(verify(b(c.publicKey), b(c.message), bad)).toBe(false);
      const otherMsg = b(c.message);
      otherMsg[0] = otherMsg[0]! ^ 1;
      expect(verify(b(c.publicKey), otherMsg, b(c.signature))).toBe(false);
    }
  });

  it("treats malformed input as invalid and refuses a disposed key", () => {
    const c = vectors.cases[0]!;
    expect(verify(b(c.publicKey).slice(1), b(c.message), b(c.signature))).toBe(false);
    expect(verify(b(c.publicKey), b(c.message), b(c.signature).slice(1))).toBe(false);
    expect(() => LeanSphincsKey.fromSeed(new Uint8Array(31))).toThrow(/32 bytes/);
    const key = LeanSphincsKey.fromSeed(b(c.seed));
    key.dispose();
    expect(() => key.sign(b(c.message))).toThrow(/disposed/);
  });

  it("builds a key and signs fast enough for an interactive payment", () => {
    const seed = new Uint8Array(32).fill(3);
    const t0 = performance.now();
    const key = LeanSphincsKey.fromSeed(seed);
    const t1 = performance.now();
    const sig = key.sign(new Uint8Array(32).fill(4));
    const t2 = performance.now();
    console.log(`WASM keygen ${(t1 - t0).toFixed(0)} ms, sign ${(t2 - t1).toFixed(0)} ms`);
    expect(verify(key.publicKey, new Uint8Array(32).fill(4), sig)).toBe(true);
    expect(t1 - t0).toBeLessThan(20_000);
    expect(t2 - t1).toBeLessThan(5_000);
    key.dispose();
  });
});
